import { useState } from 'react'
import { Button, Title2, makeStyles, tokens } from '@fluentui/react-components'
import type { Card, Lane as LaneData } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'
import CardItem from './CardItem'
import AddCardForm from './AddCardForm'
import CardDetailDialog from './CardDetailDialog'

const useStyles = makeStyles({
  lane: {
    minWidth: '260px',
    maxWidth: '320px',
    backgroundColor: tokens.colorNeutralBackground2,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalM,
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  cards: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
  emptySlot: {
    height: '40px',
    borderRadius: tokens.borderRadiusMedium,
    border: `1px dashed ${tokens.colorNeutralStroke2}`,
  },
})

interface LaneProps {
  lane: LaneData
  callerRole: BoardRole
  onDelete: (boardId: string, laneId: string) => void
}

export default function Lane({ lane, callerRole, onDelete }: LaneProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'
  const [editingCard, setEditingCard] = useState<Card | null>(null)
  const [editDialogOpen, setEditDialogOpen] = useState(false)
  const [deletingCard, setDeletingCard] = useState<Card | null>(null)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)

  const sortedCards = [...lane.cards].sort((a, b) => a.position - b.position)

  const openEdit = (card: Card) => {
    setEditingCard(card)
    setEditDialogOpen(true)
  }

  const openDelete = (card: Card) => {
    setDeletingCard(card)
    setDeleteDialogOpen(true)
  }

  return (
    <section className={styles.lane} aria-label={`Lane: ${lane.name}`}>
      <div className={styles.header}>
        <Title2 as="h2">{lane.name}</Title2>
        {canModify && (
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete lane ${lane.name}`}
            onClick={() => onDelete(lane.boardId, lane.id)}
          >
            Delete
          </Button>
        )}
      </div>
      <div className={styles.cards}>
        {sortedCards.length === 0 && !canModify && (
          <div className={styles.emptySlot} aria-hidden="true" />
        )}
        {sortedCards.map((card) => (
          <CardItem
            key={card.id}
            card={card}
            callerRole={callerRole}
            onEdit={openEdit}
            onDelete={openDelete}
          />
        ))}
      </div>
      {canModify && <AddCardForm boardId={lane.boardId} laneId={lane.id} />}
      {editingCard && (
        <CardDetailDialog
          key={editingCard.id}
          card={editingCard}
          open={editDialogOpen}
          onClose={() => setEditDialogOpen(false)}
        />
      )}
      {deletingCard && (
        <CardDetailDialog
          key={`delete-${deletingCard.id}`}
          card={deletingCard}
          open={deleteDialogOpen}
          onClose={() => setDeleteDialogOpen(false)}
          initialConfirmDelete={true}
        />
      )}
    </section>
  )
}

import {
  FluentProvider,
  Spinner,
  Title1,
  makeStyles,
  tokens,
  webLightTheme,
} from '@fluentui/react-components'
import { useParams } from 'react-router-dom'
import { useBoard } from '../hooks/useBoard'
import { useCurrentUser } from '../hooks/useCurrentUser'
import { useDeleteLane } from '../hooks/useDeleteLane'
import Lane from '../components/board/Lane'
import AddLaneForm from '../components/board/AddLaneForm'

const useStyles = makeStyles({
  root: {
    padding: tokens.spacingHorizontalXXL,
    overflowX: 'auto',
  },
  header: {
    marginBottom: tokens.spacingVerticalL,
  },
  lanes: {
    display: 'flex',
    gap: tokens.spacingHorizontalM,
    alignItems: 'flex-start',
    overflowX: 'auto',
    paddingBottom: tokens.spacingVerticalM,
  },
})

export default function BoardPage() {
  const styles = useStyles()
  const { boardId } = useParams<{ boardId: string }>()
  const { data: board, isPending } = useBoard(boardId ?? '')
  const { user } = useCurrentUser()
  const deleteLaneMutation = useDeleteLane()

  const handleDeleteLane = (bId: string, laneId: string) => {
    deleteLaneMutation.mutate({ boardId: bId, laneId })
  }

  if (isPending) return <Spinner label="Loading board…" />

  if (!board) return null

  const sortedLanes = [...board.lanes].sort((a, b) => a.position - b.position)

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <div className={styles.header}>
          <Title1 as="h1">{board.name}</Title1>
        </div>
        <div className={styles.lanes}>
          {sortedLanes.map((lane) => (
            <Lane
              key={lane.id}
              lane={lane}
              callerRole={board.callerRole}
              onDelete={handleDeleteLane}
            />
          ))}
        </div>
        {(board.callerRole === 'Owner' ||
          board.callerRole === 'Member' ||
          user?.systemRole === 'admin') && <AddLaneForm boardId={board.id} />}
      </div>
    </FluentProvider>
  )
}

import { Button, Text, Badge, makeStyles, tokens } from '@fluentui/react-components'
import { NoteRegular } from '@fluentui/react-icons'
import type { Card } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'

const useStyles = makeStyles({
  card: {
    backgroundColor: tokens.colorNeutralBackground1,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalS,
    paddingLeft: tokens.spacingHorizontalM,
    paddingRight: tokens.spacingHorizontalS,
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    gap: tokens.spacingHorizontalS,
    boxShadow: tokens.shadow2,
    cursor: 'default',
  },
  body: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
    flex: 1,
    minWidth: 0,
  },
  meta: {
    display: 'flex',
    alignItems: 'center',
    gap: tokens.spacingHorizontalXS,
  },
})

interface CardItemProps {
  card: Card
  callerRole: BoardRole
  onEdit: (card: Card) => void
  onDelete: (card: Card) => void
}

export default function CardItem({ card, callerRole, onEdit, onDelete }: CardItemProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'

  return (
    <article className={styles.card}>
      <div className={styles.body}>
        <Text>{card.title}</Text>
        <div className={styles.meta}>
          {card.dueDate && (
            <Badge appearance="outline" size="small">
              {card.dueDate}
            </Badge>
          )}
          {card.description && (
            <span role="img" aria-label="has description">
              <NoteRegular fontSize={14} aria-hidden="true" />
            </span>
          )}
        </div>
      </div>
      {canModify && (
        <>
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Edit card ${card.title}`}
            onClick={() => onEdit(card)}
          >
            Edit
          </Button>
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete card ${card.title}`}
            onClick={() => onDelete(card)}
          >
            Delete card
          </Button>
        </>
      )}
    </article>
  )
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import type { ApiError } from './useBoards'
import type { Card } from './useBoard'

interface CreateCardVars {
  boardId: string
  laneId: string
  title: string
  description?: string | null
  dueDate?: string | null
}

async function createCard(vars: CreateCardVars): Promise<Card> {
  const response = await fetch(`/api/v1/boards/${vars.boardId}/lanes/${vars.laneId}/cards`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      title: vars.title,
      description: vars.description ?? null,
      dueDate: vars.dueDate ?? null,
    }),
  })
  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw { status: response.status, code: body.code, title: body.title } as ApiError
  }
  return response.json() as Promise<Card>
}

export function useCreateCard() {
  const queryClient = useQueryClient()
  return useMutation<Card, ApiError, CreateCardVars>({
    mutationFn: createCard,
    onSettled: (_data, _error, { boardId }) =>
      queryClient.invalidateQueries({ queryKey: ['boards', boardId] }),
    retry: false,
  })
}

import { useQuery } from '@tanstack/react-query'
import type { ApiError, BoardRole } from './useBoards'

export interface Card {
  id: string
  laneId: string
  boardId: string
  title: string
  description: string | null
  dueDate: string | null
  position: number
  version: number
}

export interface Lane {
  id: string
  boardId: string
  name: string
  position: number
  version: number
  cards: Card[]
}

export interface BoardDetail {
  id: string
  name: string
  createdByUserId: string
  createdAt: string
  callerRole: BoardRole
  lanes: Lane[]
}

async function fetchBoard(boardId: string): Promise<BoardDetail> {
  const response = await fetch(`/api/v1/boards/${boardId}`)
  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw { status: response.status, code: body.code, title: body.title } as ApiError
  }
  return response.json() as Promise<BoardDetail>
}

export function useBoard(boardId: string) {
  return useQuery({
    queryKey: ['boards', boardId],
    queryFn: () => fetchBoard(boardId),
    enabled: Boolean(boardId),
  })
}

